/**
 * The built-in themes that ship as JSON files in dist/themes (generated by scripts/import-themes.js)
 * next to the ones defined in builtins.ts. The index lists names and swatches for the picker; a
 * theme's full palette is fetched only when it is selected or duplicated. Everything read from the
 * files goes through the same validation as imported themes.
 */
import { THEME_ID_PATTERN } from "../../core/definitions";
import { fetchExtensionJson } from "../../core/settings";
import { parseColor } from "./color";
import { validateTheme, type Theme, type ThemeMode } from "./theme";

export interface CatalogEntry {
  id: string;
  name: string;
  mode: ThemeMode;
  /** bg, fg, accent, red, green, yellow, blue: the chip circles. */
  colors: string[];
}

const DIR = "dist/themes";
const SWATCHES = 7;

/** Keeps only well-formed entries; a malformed file yields fewer entries, never a throw. */
export function parseIndex(value: unknown): CatalogEntry[] {
  if (!Array.isArray(value)) return [];
  const entries: CatalogEntry[] = [];
  for (const item of value) {
    if (typeof item !== "object" || item === null) continue;
    const { id, name, mode, colors } = item as Record<string, unknown>;
    if (
      typeof id !== "string" || !THEME_ID_PATTERN.test(id) ||
      typeof name !== "string" || !name.trim() || name.length > 60 ||
      (mode !== "light" && mode !== "dark") ||
      !Array.isArray(colors) || colors.length !== SWATCHES ||
      !colors.every((color) => typeof color === "string" && parseColor(color))
    ) continue;
    entries.push({ id, name: name.trim(), mode, colors: colors as string[] });
  }
  return entries;
}

/** The chip colors of a full theme, in the same order as a catalog entry. */
export const swatches = (theme: Theme): string[] => {
  const p = theme.palette;
  return [p.bg, p.fg, p.accent, p.red, p.green, p.yellow, p.blue];
};

let indexPromise: Promise<CatalogEntry[]> | undefined;
const themes = new Map<string, Promise<Theme | undefined>>();

/** Loaded once; a failure is logged and gives an empty catalog (retried on the next page load). */
export function loadCatalogIndex(): Promise<CatalogEntry[]> {
  indexPromise ??= fetchExtensionJson(`${DIR}/index.json`).then(parseIndex).catch((error) => {
    console.warn("[gha] themes: could not load the catalog", error);
    return [];
  });
  return indexPromise;
}

export function loadCatalogTheme(id: string): Promise<Theme | undefined> {
  if (!THEME_ID_PATTERN.test(id)) return Promise.resolve(undefined);
  let loaded = themes.get(id);
  if (!loaded) {
    loaded = fetchExtensionJson(`${DIR}/${id}.json`)
      .then((value) => {
        const theme = validateTheme(value);
        return theme.id === id ? theme : undefined;
      })
      // Quiet: an id that is not one of our files (for example an imported custom theme) lands here.
      .catch(() => undefined);
    themes.set(id, loaded);
  }
  return loaded;
}
